exercise.solution:
use std::fmt;
use std::num::ParseIntError;

const MAX_QUANTITY: u32 = 10;
const UNIT_PRICE: u32 = 4;

#[derive(Debug, PartialEq)]
enum OrderError {
    BadNumber(ParseIntError),
    Zero,
    TooMany(u32),
}

impl From<ParseIntError> for OrderError {
    fn from(e: ParseIntError) -> OrderError {
        OrderError::BadNumber(e)
    }
}

impl fmt::Display for OrderError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            OrderError::BadNumber(e) => write!(f, "not a number ({e})"),
            OrderError::Zero => write!(f, "quantity must be at least 1"),
            OrderError::TooMany(n) => write!(f, "{n} is more than the limit of {MAX_QUANTITY}"),
        }
    }
}

fn parse_quantity(text: &str) -> Result<u32, OrderError> {
    let quantity: u32 = text.parse()?;
    if quantity == 0 {
        return Err(OrderError::Zero);
    }
    if quantity > MAX_QUANTITY {
        return Err(OrderError::TooMany(quantity));
    }
    Ok(quantity)
}

fn total_price(first: &str, second: &str) -> Result<u32, OrderError> {
    let a = parse_quantity(first)?;
    let b = parse_quantity(second)?;
    Ok((a + b) * UNIT_PRICE)
}

fn main() {
    for text in ["3", "10", "11", "0", "-1", "abc", ""] {
        match parse_quantity(text) {
            Ok(q) => println!("[{text}] quantity {q}"),
            Err(e) => println!("[{text}] error: {e}"),
        }
    }

    for (a, b) in [("2", "3"), ("9", "9"), ("2", "many"), ("0", "3")] {
        match total_price(a, b) {
            Ok(total) => println!("{a} and {b}: total {total}"),
            Err(e) => println!("{a} and {b}: error: {e}"),
        }
    }

    let five = parse_quantity("5").expect("5 is a valid quantity");
    println!("expect gave {five}");
}
